import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    const cachedItems = [
      NewsModel(title: 'Кэш 1', link: 'https://example.com/cached-1', date: DateTime.now()),
      NewsModel(title: 'Кэш 2', link: 'https://example.com/cached-2', date: DateTime.now()),
    ];

    const freshItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
    ];

    setUp(() {
      when(mockNewsRepository.loadCachedNews()).thenAnswer((_) async => cachedItems);
      when(mockNewsRepository.refreshNewsFeed()).thenAnswer((_) async => freshItems);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display cached news immediately, then update with fresh data', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      // Сначала показываются данные из кэша мгновенно.
      expect(find.text('Кэш 1'), findsOneWidget);
      expect(find.text('Кэш 2'), findsOneWidget);
      expect(find.text('Заголовок 1'), findsNothing);
      expect(find.text('Заголовок 2'), findsNothing);

      // После завершения фоновой подгрузки — список обновляется.
      await tester.pumpAndSettle();

      expect(find.text('Кэш 1'), findsNothing);
      expect(find.text('Кэш 2'), findsNothing);
      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
    });
  });

  group('NewsRepositoryImpl cache-then-network', () {
    testWidgets('loadCachedNews returns cached items, refreshNewsFeed replaces them', (WidgetTester tester) async {
      final mockRest = MockRestDatasource();
      final mockDb = MockDbDatasource();

      when(mockDb.getNewsList()).thenAnswer((_) async => cachedItems);
      when(mockRest.getNewsList()).thenAnswer((_) async => freshItems);
      when(mockDb.saveNewsList(any)).thenAnswer((_) async {});

      final impl = NewsRepositoryImpl(mockRest, mockDb);

      // Кэш должен вернуться сразу.
      final cached = await impl.loadCachedNews();
      expect(cached.length, 2);
      expect(cached[0].title, 'Кэш 1');

      // Обновление из сети должно сохранить в кэш и вернуть свежие данные.
      final refreshed = await impl.refreshNewsFeed();
      expect(refreshed.length, 2);
      expect(refreshed[0].title, 'Заголовок 1');

      verify(mockRest.getNewsList()).called(1);
      verify(mockDb.saveNewsList(freshItems)).called(1);
    });
  });
}
